import {normalizeTF} from '/tf-utils.js';
const app=document.querySelector('#app'),toastBox=document.querySelector('#toast');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let home=null,view='home',taskId='',busy=false,refreshTimer,activeWorksheet=null;
function toast(t){toastBox.textContent=t;toastBox.style.opacity=1;setTimeout(()=>toastBox.style.opacity=0,3500)}
async function api(path,payload){const opts={credentials:'same-origin'};if(payload!==undefined){opts.method='POST';opts.headers={'Content-Type':'application/json'};opts.body=JSON.stringify(payload)}const r=await fetch('/api/student/'+path,opts);const data=await r.json();if(!r.ok){if(r.status===401&&path!=='login')login();throw new Error(data.error||'요청을 처리할 수 없습니다.')}return data}
function login(error=''){clearInterval(refreshTimer);home=null;app.innerHTML=`<section class="login-shell"><a class="portal-brand" href="/">✳ 할 수 있어</a><div class="login-card"><h1>학습 화면을 불러올 수 없습니다.</h1><p>${esc(error||'서버 연결을 확인하고 다시 열어 주세요.')}</p><a class="btn" href="/student">다시 접속 →</a></div></section>`}
const task=()=>home?.tasks.find(t=>t.id===taskId);
const status=t=>({waiting:'채점 대기',review:'교사 검토 중',ready:'오답 학습 대기','in-progress':'오답 학습 중',success:'학습 완료',retry:'재학습 필요',clear:'오답 없음'}[t.status]||'학습 준비 중');
function shell(body){const s=home.student;app.innerHTML=`<header class="student-header"><a href="/student" class="portal-brand">✳ 할 수 있어</a><div><span>${esc(s.className)}</span><strong>${esc(s.name)}</strong><a class="text-button" href="/">시작 화면</a></div></header><main class="student-main"><nav class="student-nav"><button data-view="home" class="${view==='home'?'active':''}">오답노트</button><button data-view="records" class="${view==='records'?'active':''}">학습 기록</button></nav>${body}<footer>${home.aiConfigured?'AI 연결 모드':'시연 모드 · 밀도 단원'} · 개인 답안·학습 결과</footer></main>`}
function render(){if(!home)return;const s=home.student;
 if(view==='worksheet'){renderWorksheet();return}
 if(view==='learn'){renderLearn();return}
 if(view==='records'){shell(`<section class="student-welcome"><h1>학습 기록</h1><p>학습지 점수와 확인 문제 결과를 확인하세요.</p></section><section class="student-records">${home.tasks.map(t=>`<article><div><span class="student-kicker">${esc(status(t))}</span><h2>${esc(t.title)}</h2><p>학습지 점수 ${t.score===null?'미제출':t.score+'점'} ${t.pendingCount?'· 교사 검토 '+t.pendingCount+'문항':''}</p>${t.session?.verification?`<p class="record-feedback">${esc(t.session.verification.feedback)}</p>`:''}</div><span class="record-state">${t.status==='success'?'✓':t.status==='retry'?'↻':'○'}</span></article>`).join('')||'<p>학습 기록이 없습니다.</p>'}</section>`);return}
 const next=home.tasks.find(t=>['ready','in-progress','retry'].includes(t.status))||home.tasks[0];
 shell(`<section class="student-welcome"><h1>오답노트</h1><p>틀린 문제를 다시 학습하고 결과를 확인하세요.</p></section>${next?`<section class="student-feature"><div class="student-feature-copy"><span class="student-kicker">${esc(status(next))}</span><h2>${esc(next.concept||next.title)}</h2><p>${esc(next.title)}</p><div class="student-path"><span>질문 3회</span><i>→</i><span>확인 문제</span></div>${['ready','in-progress','retry','success'].includes(next.status)?`<button class="btn" data-open="${next.id}">${next.session?.verification?'학습 결과 보기':next.session?'학습 이어하기':'오답 학습 시작'} →</button>`:`<div class="student-wait">${next.status==='clear'?'오답이 없습니다.':'교사가 답안을 채점하면 오답 학습을 시작할 수 있습니다.'}</div>`}</div><div class="student-mascot" aria-hidden="true"><span>✳</span></div></section>`:'<section class="student-feature"><h2>배정된 학습지가 없습니다.</h2></section>'}<section class="student-task-list"><div class="cardhead"><h2>학습지 목록 <small>${home.tasks.length}</small></h2><button class="text-button" data-action="refresh">새로고침 ↻</button></div>${home.tasks.map(t=>`<article><div><h3>${esc(t.title)}</h3><p>${t.questionCount}문항 · ${esc(status(t))}</p></div><button class="btn light" data-solve="${esc(t.id)}">${t.submitted?'답안 수정':'문제 풀기'}</button>${['ready','in-progress','retry','success'].includes(t.status)?`<button class="student-arrow" data-open="${t.id}" aria-label="${esc(t.title)} 학습 열기">→</button>`:'<span class="student-task-status">'+(t.status==='clear'?'✓':'대기')+'</span>'}</article>`).join('')}</section>`)}
function renderLearn(){const t=task();if(!t){view='home';render();return}const s=t.session;if(!s){shell('<p>학습 정보를 불러오는 중입니다.</p>');return}const previous=s.messages.slice(0,-2),latest=s.messages.slice(-2);const msg=m=>`<div class="student-message ${m.role==='student'?'mine':''}">${esc(m.text)}</div>`;
 shell(`<div class="student-learning-head"><button class="text-button" data-view="home">← 오답노트</button><span>${esc(s.concept)}</span></div><section class="student-conversation"><div class="conversation-heading"><h1>오답 학습</h1><span>${s.phase==='chat'?`질문 ${s.turnCount+1} / 3`:s.phase==='check'?'확인 문제':'학습 결과'}</span></div><div class="student-progress">${[0,1,2].map(i=>`<i class="${i<s.turnCount?'done':''}"></i>`).join('')}</div><div class="student-messages" aria-live="polite">${previous.length?`<details><summary>이전 대화 보기</summary>${previous.map(msg).join('')}</details>`:''}${latest.map(msg).join('')}${s.sources?.length?`<details><summary>참고 자료</summary><p>${s.sources.map(r=>esc(r.citation)).join(' · ')}</p></details>`:''}</div>${s.phase==='chat'?`<form id="student-turn" class="student-reply"><textarea name="answer" aria-label="답변" placeholder="풀이 과정이나 이유를 입력하세요." required maxlength="2000" rows="2" ${busy?'disabled':''}></textarea><button class="btn" ${busy?'disabled':''}>${busy?'답변 확인 중…':'답변 제출 ↑'}</button></form>`:s.phase==='check'?`<div class="student-independent"><span class="student-kicker">확인 문제 · 힌트 없음</span><h2>${esc(s.check?.text)}</h2><form id="student-verify"><input name="answer" aria-label="확인 문제 답안" placeholder="답안을 입력하세요" required maxlength="2000" ${busy?'disabled':''}><button class="btn" ${busy?'disabled':''}>${busy?'확인 중…':'답안 제출 ✓'}</button></form></div>`:`<div class="student-complete ${s.verification.correct?'success':''}"><span class="complete-symbol">${s.verification.correct?'✓':'↻'}</span><h2>${s.verification.correct?'확인 문제 정답':'재학습 필요'}</h2><p>${esc(s.verification.feedback)}</p><div class="student-saved">✓ 학습 결과가 교사에게 전달되었습니다.</div><div class="toolbar"><button class="btn" data-view="home">오답노트로</button><button class="btn light" data-action="restart">다시 학습하기</button></div></div>`}</section>`)}
async function refresh(){home=await api('home');render()}
function renderWorksheet(){const w=activeWorksheet;if(!w){view='home';render();return}
 shell(`<div class="student-learning-head"><button class="text-button" data-view="home">← 오답노트</button><span>학습지 풀기</span></div><section class="student-conversation"><h1>${esc(w.title)}</h1><p>문항에 맞게 답안을 입력하세요. T/F에서 F를 선택하면 틀린 부분과 바르게 고친 문장을 함께 쓰세요.</p><form id="student-worksheet-form">${w.questions.map((q,i)=>{const previous=w.answers.find(a=>a.questionId===q.id)||{},a=normalizeTF(previous.tfAnswer||previous.answer);return `<article class="tf-question"><h2>${i+1}. ${esc(q.text)}</h2>${q.type==='T/F'?`<fieldset class="tf-choices"><legend>${i+1}번 T/F 선택</legend>${['T','F'].map(v=>`<label><input type="radio" name="${esc(q.id)}__judgment" value="${v}" ${a.judgment===v?'checked':''} required> ${v==='T'?'T · 참':'F · 거짓'}</label>`).join('')}</fieldset><div class="tf-correction" data-tf-fields="${esc(q.id)}" ${a.judgment==='F'?'':'hidden'}><label>틀린 부분<textarea name="${esc(q.id)}__wrongPart" maxlength="500" rows="2" ${a.judgment==='F'?'required':''}>${esc(a.wrongPart)}</textarea></label><label>바르게 고친 문장<textarea name="${esc(q.id)}__correction" maxlength="2000" rows="3" ${a.judgment==='F'?'required':''}>${esc(a.correction)}</textarea></label></div>`:q.type==='3지선다'?`<label>답안<select name="${esc(q.id)}" required><option value="">선택하세요</option>${(q.options||[]).map((o,j)=>`<option value="${j+1}" ${String(previous.answer)===String(j+1)?'selected':''}>${j+1}. ${esc(o)}</option>`).join('')}</select></label>`:`<label>답안<textarea name="${esc(q.id)}" required maxlength="2000" rows="3">${esc(previous.answer||'')}</textarea></label>`}</article>`}).join('')}<button class="btn" type="submit">답안 제출</button><p class="tf-submit-result" role="status"></p></form></section>`)}
document.addEventListener('change',e=>{if(!e.target.matches('#student-worksheet-form input[type=radio]'))return;const qid=e.target.name.replace(/__judgment$/,''),fields=[...document.querySelectorAll('[data-tf-fields]')].find(el=>el.dataset.tfFields===qid);if(fields){fields.hidden=e.target.value!=='F';fields.querySelectorAll('textarea').forEach(el=>el.required=e.target.value==='F')}});
document.addEventListener('submit',async e=>{if(e.target.id!=='student-worksheet-form')return;e.preventDefault();if(busy)return;const f=e.target,fd=new FormData(f),w=activeWorksheet,answers=w.questions.map(q=>q.type==='T/F'?{questionId:q.id,tfAnswer:{judgment:fd.get(q.id+'__judgment'),wrongPart:fd.get(q.id+'__wrongPart'),correction:fd.get(q.id+'__correction')}}:{questionId:q.id,answer:fd.get(q.id)});busy=true;const button=f.querySelector('button[type=submit]');button.disabled=true;button.textContent='제출 중…';try{const r=await api('worksheet/submit',{worksheetId:w.id,answers});w.answers=answers;home=await api('home');f.querySelector('[role=status]').textContent=`${r.gradingMode==='ai'?'AI 채점 완료':'제출 완료'} · ${r.total}문항 중 ${r.correctCount}문항 정답${r.pendingCount?' · 교사 검토 '+r.pendingCount+'문항':''}. 교사 화면에 전달되었습니다.`;toast('답안을 제출했습니다.')}catch(err){toast(err.message)}finally{busy=false;button.disabled=false;button.textContent='답안 다시 제출'}});
async function openTask(id,restart=false){busy=true;try{const r=await api('sessions/start',{worksheetId:id,restart});const t=home.tasks.find(t=>t.id===id);t.session=r.session;taskId=id;view='learn';render()}finally{busy=false;if(home)render()}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||busy)return;try{if(b.dataset.view){view=b.dataset.view;await refresh()}if(b.dataset.solve){activeWorksheet=await api('worksheet?worksheetId='+encodeURIComponent(b.dataset.solve));view='worksheet';render()}if(b.dataset.open)await openTask(b.dataset.open);if(b.dataset.action==='refresh')await refresh();if(b.dataset.action==='restart'&&confirm('이 학습지의 대화를 다시 시작할까요?'))await openTask(taskId,true)}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,fd=new FormData(f);if(!['student-turn','student-verify'].includes(f.id))return;const answer=String(fd.get('answer')||'').trim();if(!answer)return;busy=true;render();try{const t=task(),r=await api(f.id==='student-turn'?'sessions/turn':'sessions/verify',{worksheetId:t.id,sessionId:t.session.id,answer});t.session=r.session;if(r.session.verification)t.status=r.session.verification.correct?'success':'retry';else t.status='in-progress'}catch(err){toast(err.message)}finally{busy=false;render()}});
function startRefresh(){clearInterval(refreshTimer);refreshTimer=setInterval(async()=>{if(busy||['learn','worksheet'].includes(view)||!home)return;try{const next=await api('home');if(next.revision!==home.revision||next.aiConfigured!==home.aiConfigured){home=next;render()}}catch{}},3000)}
async function bootstrap(){try{const code=new URL(location.href).searchParams.get('code');if(code){history.replaceState(null,'','/student');await api('login',{code})}else{await api('me')}await refresh();startRefresh()}catch(err){login(err.message==='로그인이 필요합니다.'?'':err.message)}}
bootstrap();
